1	import { existsSync, readFileSync, writeFileSync } from 'node:fs';
2	import { CYCLE, CYCLES } from './cycles.js';
3	import { parseDate } from './dates.js';
4	
5	/**
6	 * Where the subscriptions are kept: `--file`, else $SUBTRACK_FILE, else ./subscriptions.json.
7	 * @param {string | undefined} file
8	 * @param {Record<string, string | undefined>} [env=process.env]
9	 * @returns {string}
10	 */
11	export function storePath(file, env = process.env) {
12	  return file || env.SUBTRACK_FILE || 'subscriptions.json';
13	}
14	
15	/**
16	 * Why a subscription is not valid, or null if it is.
17	 * @param {{ name: string, price: number, cycle: string, since: string }} sub
18	 * @returns {string | null}
19	 */
20	export function validate(sub) {
21	  if (!sub || typeof sub.name !== 'string' || !sub.name.trim()) return 'a subscription needs a name';
22	  if (!Number.isInteger(sub.price) || sub.price < 0) return `${sub.name}: price must be whole cents, zero or more`;
23	  if (!CYCLES.includes(sub.cycle)) return `${sub.name}: unknown billing cycle "${sub.cycle}"`;
24	  if (parseDate(sub.since) === null) return `${sub.name}: "since" must be a date (YYYY-MM-DD)`;
25	  return null;
26	}
27	
28	// Files written by subtrack 0.1 stored "month" and "year"; read them with today's cycle names.
29	const V1_NAMES = { month: CYCLE.MONTH, year: CYCLE.YEAR };
30	
31	function upgrade(sub) {
32	  return { ...sub, cycle: V1_NAMES[sub.cycle] ?? sub.cycle };
33	}
34	
35	/**
36	 * Read every subscription from the file (none if it does not exist yet). Throws on an invalid entry.
37	 * @param {string} path
38	 * @returns {Array<{ name: string, price: number, cycle: string, since: string }>}
39	 */
40	export function load(path) {
41	  if (!existsSync(path)) return [];
42	  const subs = (JSON.parse(readFileSync(path, 'utf8')).subscriptions ?? []).map(upgrade);
43	  for (const sub of subs) {
44	    const problem = validate(sub);
45	    if (problem) throw new Error(`${path}: ${problem}`);
46	  }
47	  return subs;
48	}
49	
50	/**
51	 * Write every subscription to the file.
52	 * @param {string} path
53	 * @param {Array<{ name: string, price: number, cycle: string, since: string }>} subs
54	 */
55	export function save(path, subs) {
56	  writeFileSync(path, JSON.stringify({ subscriptions: subs }, null, 2) + '\n');
57	}
