});

test('weekly charges sort with other cycles soonest first', () => {
  const subs = [plan('Yearly', 'yearly', '2025-10-24'), plan('Weekly', 'weekly', '2026-10-10'), plan('Monthly', 'monthly', '2026-09-02')];
  const rows = upcoming(subs, '2026-10-24', 30);
